import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The Directed-HoTT Limit of the Term Calculus","description":"","frontmatter":{"title":"The Directed-HoTT Limit of the Term Calculus","type":"adr","date":"2026-09-08T00:00:00.000Z","status":"proposed","status_note":"Proposed — the calculus is a directed (∞,1)-category; 1-cells stay the engine."},"headers":[],"relativePath":"handl/project/adrs/0100-directed-hott-limit.md","filePath":"vendored/handl/project/adrs/0100-directed-hott-limit.md"}`),a={name:`handl/project/adrs/0100-directed-hott-limit.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0100-the-directed-hott-limit-of-the-term-calculus" tabindex="-1">ADR-0100: The Directed-HoTT Limit of the Term Calculus <a class="header-anchor" href="#adr-0100-the-directed-hott-limit-of-the-term-calculus" aria-label="Permalink to “ADR-0100: The Directed-HoTT Limit of the Term Calculus”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong><code>Term</code> is a 2-category</strong>: objects are sorts, 1-cells are arrows, 2-cells are rewrites between arrows.</li><li><strong><code>Language</code> is a presented 2-category</strong> — its data (sorts, arrows, rewrites) presents the theory, not a flat grammar.</li><li><strong>A <code>Model</code> is a 2-functor</strong> from the presented theory to a semantic category; the engine interprets the functor.</li><li><strong>The model family</strong> (value, type, exec, meta, transform) are 2-functors over the same <code>Term</code>; none extends the calculus.</li><li><strong>Syntax for rewrites and paths</strong> is data (<code>law</code>, <code>rewrite</code>, <code>Path</code>), not Rust arms.</li><li><strong>Univalence and transport</strong> are 1-cell operators derived from the equality type, not new primitives.</li><li><strong>Grades are propositions</strong> — a grade is a proposition about a cell, and grading is a 2-categorical construction.</li><li><strong>Directed paths</strong>: <code>Term</code> is a directed (∞,1)-category; the 2-cells are directed rewrites, not invertible in general.</li><li><strong>Implementation</strong>: add <code>Term::Rewrite</code>, <code>law</code>/<code>rewrite</code> declarations, <code>Model::rewrite</code>, make <code>plugin-engine-transform</code> the <code>OptimizerModel</code>, add <code>transport</code>/<code>equiv</code>, and the <code>Path</code> sort.</li><li><strong>Keep the 1-categorical engine</strong>: evaluation never requires 2-cells; a model may return <code>Unsupported</code> for <code>Rewrite</code> nodes.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The calculus had rewrites as an afterthought (a separate transform engine), so laws, equality and optimization were outside the semantics. The 2-category reading puts rewrites in <code>Term</code> and makes every model a 2-functor, which is the only way the optimizer and the evaluator share one theory.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep rewrites outside the calculus</strong> — the split this ADR removes.</li><li><strong>Require 2-cells to evaluate</strong> — evaluation stays 1-categorical.</li><li><strong>Invertible 2-cells only</strong> — paths are directed.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li><code>Term</code> gains <code>Rewrite</code>; models that do not optimize return <code>Unsupported</code>.</li><li><code>law</code>/<code>rewrite</code>/<code>Path</code> become language data.</li><li>The optimizer becomes a <code>Model</code>, not a side engine.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>engine/</code> — <code>Term</code>, <code>Model</code>, <code>Rewrite</code>.</li><li><code>crates/handl-kit-data-canonical/data/</code> — <code>law</code>/<code>rewrite</code>/<code>Path</code> rows.</li><li><code>engine-transform*</code> — the <code>OptimizerModel</code>.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+The 2-category presentation, model family, univalence/transport, grades and the +directed limit: +<a href="./../design/0100-directed-hott-limit.html"><code>design/0100-directed-hott-limit.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};